export function clampPanelPosition(point,size,bounds){return {x:Math.max(bounds.left,Math.min(point.x,Math.max(bounds.left,bounds.right-size.width))),y:Math.max(bounds.top,Math.min(point.y,Math.max(bounds.top,bounds.bottom-size.height)))};}
export class DraggableSectorPanel {
 constructor(panel,handle,reset){this.panel=panel;this.handle=handle;this.position=null;this.drag=null;this.safeProbe=document.createElement('div');Object.assign(this.safeProbe.style,{position:'fixed',visibility:'hidden',pointerEvents:'none',padding:'env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left)'});document.querySelector('#map').append(this.safeProbe);this.abort=new AbortController();const options={signal:this.abort.signal};handle.style.touchAction='none';handle.tabIndex=0;handle.setAttribute('aria-label','섹터 정보 이동: 제목을 끌거나 방향키 사용');
  handle.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button,a,input,select'))return;const rect=panel.getBoundingClientRect();this.drag={id:e.pointerId,x:e.clientX,y:e.clientY,origin:{x:rect.x,y:rect.y},moved:false};handle.setPointerCapture(e.pointerId);e.stopPropagation();},options);
  handle.addEventListener('pointermove',e=>{const d=this.drag;if(!d||d.id!==e.pointerId)return;e.stopPropagation();const dx=e.clientX-d.x,dy=e.clientY-d.y;if(!d.moved&&Math.hypot(dx,dy)<7)return;d.moved=true;panel.classList.add('is-dragging');this.place({x:d.origin.x+dx,y:d.origin.y+dy});},options);
  const end=e=>{if(this.drag?.id!==e.pointerId)return;e.stopPropagation();if(handle.hasPointerCapture(e.pointerId))handle.releasePointerCapture(e.pointerId);this.drag=null;panel.classList.remove('is-dragging');};for(const name of ['pointerup','pointercancel','lostpointercapture'])handle.addEventListener(name,end,options);
  handle.addEventListener('keydown',e=>{const directions={ArrowLeft:[-10,0],ArrowRight:[10,0],ArrowUp:[0,-10],ArrowDown:[0,10]};if(!directions[e.key])return;e.preventDefault();e.stopPropagation();const r=panel.getBoundingClientRect(),[x,y]=directions[e.key],scale=e.shiftKey?5:1;this.place({x:r.x+x*scale,y:r.y+y*scale});},options);
  reset.addEventListener('click',()=>this.reset(),options);for(const name of ['resize','orientationchange'])window.addEventListener(name,()=>this.scheduleClamp(),options);document.addEventListener('fullscreenchange',()=>this.scheduleClamp(),options);window.visualViewport?.addEventListener('resize',()=>this.scheduleClamp(),options);
 }
 bounds(){const width=window.innerWidth,height=window.innerHeight,toolbar=document.querySelector('#surface-toolbar').getBoundingClientRect(),hud=document.querySelector('.top-hud').getBoundingClientRect(),timeline=document.querySelector('.timeline').getBoundingClientRect();const safe=getComputedStyle(this.safeProbe),left=Math.max(14,parseFloat(safe.paddingLeft)||0),right=Math.max(14,parseFloat(safe.paddingRight)||0),top=parseFloat(safe.paddingTop)||0,bottom=Math.max(14,parseFloat(safe.paddingBottom)||0);return {left,top:Math.max(hud.bottom,toolbar.bottom,top)+1,right:width-right,bottom:Math.min(height-bottom,timeline.top>0?timeline.top-6:height-bottom)};}
 place(point){if(this.panel.hidden)return;const r=this.panel.getBoundingClientRect(),p=clampPanelPosition(point,r,this.bounds());this.position=p;Object.assign(this.panel.style,{left:p.x+'px',top:p.y+'px',right:'auto',bottom:'auto'});}
 refresh(){if(this.panel.hidden)return;if(this.position)this.place(this.position);}
 scheduleClamp(){cancelAnimationFrame(this.frame);this.frame=requestAnimationFrame(()=>{if(this.panel.hidden)return;const r=this.panel.getBoundingClientRect();this.place(this.position??{x:r.x,y:r.y});});}
 reset(){this.position=null;for(const key of ['left','top','right','bottom'])this.panel.style.removeProperty(key);this.scheduleClamp();}
 dispose(){this.abort.abort();cancelAnimationFrame(this.frame);this.safeProbe.remove();}
}
